// MOCK ТОЛЬКО SocialCrawl. Следующая AI Agent-нода использует настоящий OpenRouter.
const cfg = $input.first().json;
const now = Date.now();
const ago = (minutes) => new Date(now - minutes * 60000).toISOString();
const item = (id, user, name, text, minutes, city, views, likes, replies, reposts, comments = []) => ({
  id,
  url: 'https://www.threads.com/@' + user + '/post/' + id,
  text,
  published_at: ago(minutes),
  author: { username: user, display_name: name, bio: city + ', Беларусь', location: city },
  engagement: { views, likes, replies, reposts },
  comments: comments.map((value, index) => ({ id: id + '_c' + index, text: value })),
});

const items = [
  item('MOCKBY001', 'minsk_driver', 'Алексей', 'Сбер, почему перевод в BYN завис уже на шесть часов? Поддержка отвечает шаблонами. Минск.', 35, 'Минск', 18400, 420, 96, 38, ['У меня вчера было так же', 'Напишите номер обращения', 'После повторного звонка перевод дошёл']),
  item('MOCKBY002', 'olga_brest', 'Ольга', 'Спасибо @sberbank: быстро заблокировали карту после подозрительной операции и всё объяснили. Брест.', 58, 'Брест', 9200, 610, 42, 55, ['Редко хвалят поддержку, но тут заслуженно', 'А деньги уже вернули?']),
  item('MOCKBY003', 'gomel_finance', 'Денис', 'Кто пользовался накопительным счётом Сбер? Интересуют реальные условия и снятие без потери процентов. Гомель.', 76, 'Гомель', 6400, 180, 73, 21, ['Смотрите условия по минимальному остатку', 'Процент меняется, проверяйте приложение']),
  item('MOCKBY004', 'vitebsk_shop', 'Марина', 'Осторожно: в Viber пишут якобы от Сбер и просят назвать код. Это мошенники. Витебск, предупредите родителей.', 110, 'Витебск', 31800, 1200, 205, 310, ['Маме сегодня тоже написали', 'Банк никогда не просит код', 'Куда отправить номер мошенника?']),
  item('MOCKBY005', 'hrodna_today', 'Гродно сегодня', 'Приложение Sber сегодня дважды выбросило на вход. У кого ещё так в Гродно?', 145, 'Гродно', 22100, 530, 187, 44, ['Есть такая проблема', 'На Android после обновления', 'У меня работает нормально']),
  item('MOCKBY006', 'mogilev_family', 'Семья из Могилёва', 'В отделении Сбер в Могилёве сотрудница спокойно помогла пожилому человеку настроить оплату ЖКХ. Хороший сервис.', 195, 'Могилёв', 5700, 390, 28, 19, ['Такие истории приятно читать']),
  item('MOCKBY007', 'pinsk_business', 'Бизнес Пинска', 'Эквайринг Сбер списал комиссию выше ожидаемой. Пинск, малый бизнес. Нужен понятный разбор тарифа.', 225, 'Пинск', 12800, 270, 84, 30, ['Проверьте категорию операции', 'У нас комиссия тоже выросла']),
  item('MOCKBY008', 'bobruisk_student', 'Студент', 'Есть ли у Сбер нормальная карта для студента в Беларуси без платного обслуживания?', 260, 'Бобруйск', 4100, 95, 61, 12, ['Есть молодёжный вариант', 'Сравните кешбэк и стоимость']),
  item('MOCKBY009', 'minsk_cafe', 'Кафе в Минске', 'Терминал @sber перестал принимать оплату в обед, очередь в кафе. Минск. Через 20 минут заработал.', 310, 'Минск', 15400, 350, 112, 47, ['В соседнем магазине тоже было', 'Главное, что быстро восстановили']),
  item('MOCKBY010', 'baranovichi_mom', 'Ирина', 'Получила кешбэк от Сбер за покупки — всё начислилось правильно и вовремя. Барановичи.', 390, 'Барановичи', 3600, 245, 17, 11, ['Какая категория была повышенная?']),
  item('MOCKBY011', 'lida_news', 'Новости Лиды', 'В Лиде появилось объявление о вакансии от имени Sberbank. Кто знает, это официальный набор?', 470, 'Лида', 7400, 140, 52, 24, ['Проверьте домен почты', 'Похоже на старое объявление']),
  item('MOCKBY012', 'soligorsk_user', 'Павел', 'Сбер прислал уведомление о техработах заранее. Нейтрально: ночью часть функций будет недоступна. Солигорск.', 620, 'Солигорск', 2900, 76, 14, 5),
  // Должны быть отброшены: нет подтверждённой связи с Беларусью.
  item('MOCKFOREIGN1', 'moscow_user', 'Иван', 'Сбер снова изменил условия обслуживания.', 90, 'Москва', 50000, 900, 300, 200),
  item('MOCKFOREIGN2', 'prague_life', 'Pavel', 'Question about Sberbank service in Europe.', 130, 'Прага', 8000, 100, 20, 4),
];

// У иностранных контрольных записей специально убираем Belarus из mock-профиля.
items.find((value) => value.id === 'MOCKFOREIGN1').author = { username: 'moscow_user', display_name: 'Иван', bio: 'Москва, Россия', location: 'Москва' };
items.find((value) => value.id === 'MOCKFOREIGN2').author = { username: 'prague_life', display_name: 'Pavel', bio: 'Praha, Czechia', location: 'Praha' };

return [{ json: { success: true, platform: 'threads', endpoint: '/v1/threads/search', data: { items, total: items.length, dropped: 0 }, mock_config: cfg } }];

const cfg = $('01 · Настройка бренда и окна').first().json;
const inputs = $input.all();
const startMs = Date.parse(cfg.window_start_iso);
const endMs = Date.parse(cfg.window_end_iso);
const blocked = /(?:\b18\s*\+|порн|эрот|интим|onlyfans|эскорт|проститу|наркот|казино|букмекер|политик|выбор|президент|правительств|парламент|депутат|министр|геополит|санкци|войн|военн|обстрел|ракет|оппозици|митинг|протест)/iu;
const rb = /(?:беларус|белорус|беларуск|belarus|\bby\b|\bbyn\b|минск|minsk|гомел|gomel|homiel|брест|brest|витебск|vitebsk|могил[её]в|mogilev|гродно|grodno|hrodna|бобруйск|баранович|полоцк|новополоцк|солигорск|жодино|лида|пинск|мозыр|орша|борисов|молодечно|\bрб\b|бел\.?\s*руб)/iu;

const cleanFilterText = (value) => String(value || '')
  .replace(/https?:\/\/\S+/giu, ' ')
  .replace(/www\.\S+/giu, ' ')
  .replace(/@[\p{L}\p{N}_.]+/gu, ' ')
  .replace(/#[\p{L}\p{N}_]+/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const isRussianText = (value) => {
  const source = cleanFilterText(value);
  const letters = source.match(/\p{L}/gu) || [];
  if (!letters.length) return false;
  const ru = (source.match(/[А-Яа-яЁё]/g) || []).length;
  const latin = (source.match(/[A-Za-z]/g) || []).length;
  const foreign = (source.match(/[ІіЇїЄєҐґЎў]/g) || []).length;
  const f = cfg.language_filter || {};
  return ru >= Number(f.minRussianLetters || 5)
    && ru / letters.length >= Number(f.minRussianShare || 0.70)
    && latin / letters.length <= Number(f.maxLatinShare || 0.30)
    && (!f.rejectForeignCyrillic || foreign === 0);
};
const geoStop = new RegExp(cfg.geo_stop_pattern || '(?!)', 'iu');
const profanityStop = new RegExp(cfg.profanity_pattern || '(?!)', 'iu');
const socialSpamStop = new RegExp(cfg.social_spam_pattern || '(?!)', 'iu');
const extendedTopicStop = /(?:политик\p{L}*|межнациональн\p{L}*|межэтническ\p{L}*|конфликт\p{L}*|столкновени\p{L}*|вражд\p{L}*|противостояни\p{L}*|аборт\p{L}*|прерыван\p{L}*\s+беременн\p{L}*|эвтанази\p{L}*|религи\p{L}*|церков\p{L}*|христиан\p{L}*|православ\p{L}*|католиц\p{L}*|ислам\p{L}*|мусульман\p{L}*|иудаизм\p{L}*|атеизм\p{L}*|аллах\p{L}*|господ\p{L}*|(?:^|[^\p{L}])бог(?:а|у|ом|е|и)?(?=$|[^\p{L}])|секс\p{L}*|сексуальн\p{L}*|цензур\p{L}*|домашн\p{L}*\s+насили\p{L}*|семейн\p{L}*\s+насили\p{L}*|абьюз\p{L}*|интимн\p{L}*\s+подробност\p{L}*|половы\p{L}*\s+орган\p{L}*|менструац\p{L}*|эрекци\p{L}*|эякуляц\p{L}*|чайлдфри\p{L}*|childfree|гендерн\p{L}*\s+(?:равенств\p{L}*|неравенств\p{L}*)|феминиз\p{L}*|сексизм\p{L}*|эйджизм\p{L}*|дискриминаци\p{L}*|расизм\p{L}*|расист\p{L}*|экстремистск\p{L}*\s+(?:символик\p{L}*|атрибут\p{L}*)|свастик\p{L}*|национализм\p{L}*|националист\p{L}*|нацизм\p{L}*|нацист\p{L}*|неонаци\p{L}*|наркот\p{L}*|кокаин\p{L}*|героин\p{L}*|марихуан\p{L}*|каннабис\p{L}*|гашиш\p{L}*|амфетамин\p{L}*|метамфетамин\p{L}*|мефедрон\p{L}*|экстази\p{L}*|психотроп\p{L}*|оружи\p{L}*|пистолет\p{L}*|винтовк\p{L}*|огнестрельн\p{L}*|боеприпас\p{L}*|взрывчат\p{L}*|суицид\p{L}*|самоубий\p{L}*|самоповреждени\p{L}*)/iu;
const criticismStop = /(?:критик\p{L}*|недовольств\p{L}*|возмущ\p{L}*|обвин\p{L}*|жалоб\p{L}*|претензи\p{L}*|бездейств\p{L}*|произвол\p{L}*|коррупц\p{L}*|репресси\p{L}*|некомпетент\p{L}*|неэффектив\p{L}*|нарушени\p{L}*|провал\p{L}*)/iu;
const governmentStop = /(?:государственн\p{L}*\s+(?:институт\p{L}*|орган\p{L}*)|орган\p{L}*\s+власт\p{L}*|власт\p{L}*|правительств\p{L}*|парламент\p{L}*|министерств\p{L}*|ведомств\p{L}*|администраци\p{L}*|чиновник\p{L}*|прокуратур\p{L}*|милици\p{L}*|полици\p{L}*|суд\p{L}*)/iu;


const escRe = (value) => String(value).replace(/[.*+?^{}$()|[\]\\]/g, '\\$&');
const aliasSource = cfg.brand_aliases.map((value) => escRe(String(value).replace(/^@/, ''))).sort((a, b) => b.length - a.length).join('|');
const mention = new RegExp('(?:^|[^\\p{L}\\p{N}_])@?(?:' + aliasSource + ')(?=$|[^\\p{L}\\p{N}_])', 'iu');
const first = (...values) => values.find((value) => value !== undefined && value !== null && value !== '');
const num = (...values) => {
  const value = first(...values);
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
};
const textOf = (value) => typeof value === 'string' ? value : value ? JSON.stringify(value) : '';
const wrappers = [];
for (const input of inputs) {
  const body = input.json || {};
  const list = Array.isArray(body?.data?.items) ? body.data.items
    : Array.isArray(body?.items) ? body.items
    : Array.isArray(body?.data?.posts) ? body.data.posts
    : Array.isArray(body?.posts) ? body.posts
    : Array.isArray(body?.results) ? body.results
    : Array.isArray(body?.data) ? body.data : [];
  wrappers.push(...list);
}

const unique = new Map();
for (const wrapper of wrappers) {
  const post = wrapper?.post || wrapper;
  const id = String(first(post?.id, wrapper?.id, post?.url, wrapper?.url, ''));
  if (id && !unique.has(id)) unique.set(id, wrapper);
}

const posts = [];
for (const [id, wrapper] of unique.entries()) {
  const post = wrapper?.post || wrapper;
  const content = post?.content || {};
  const author = post?.author || wrapper?.author || {};
  const engagement = post?.engagement || wrapper?.engagement || {};
  const sourceText = String(first(content?.text, post?.text, wrapper?.text, '')).trim();
  const username = String(first(author?.username, author?.handle, 'unknown')).replace(/^@/, '');
  const authorName = String(first(author?.display_name, author?.name, username));
  const locationText = [author?.location, author?.bio, author?.country, post?.location, post?.place, post?.geo, wrapper?.location, wrapper?.place, wrapper?.geo].map(textOf).join(' ');
  const searchable = [sourceText, username, authorName, locationText].join(' ');
  const publishedAt = String(first(post?.published_at, wrapper?.published_at, post?.created_at, wrapper?.created_at, ''));
  const publishedMs = Date.parse(publishedAt);
  const countryCode = String(first(author?.country_code, post?.country_code, wrapper?.country_code, '')).toUpperCase();
  if (!sourceText || !mention.test(sourceText)) continue;
  if (cfg.strict_russian_only && !isRussianText(sourceText)) continue;
  if (cfg.reject_profanity && profanityStop.test(sourceText)) continue;
  if (cfg.reject_social_spam && socialSpamStop.test(sourceText)) continue;
  if (cfg.geo_stop_enabled && geoStop.test(searchable)) continue;
  if (
    blocked.test(searchable)
    || extendedTopicStop.test(searchable)
    || (criticismStop.test(searchable) && governmentStop.test(searchable))
  ) continue;
  if (!Number.isFinite(publishedMs) || publishedMs < startMs || publishedMs > endMs) continue;
  if (!(countryCode === 'BY' || rb.test(searchable))) continue;

  const candidateLists = [wrapper?.comments, wrapper?.replies, post?.comments, post?.replies, post?.ext?.comments, post?.ext?.replies].filter(Array.isArray);
  const commentSamples = [];
  for (const list of candidateLists) {
    for (const entry of list) {
      const value = String(entry?.content?.text || entry?.text || entry?.body || entry?.comment_text || '').trim();
      if (value && !commentSamples.includes(value)) commentSamples.push(value.slice(0, 280));
      if (commentSamples.length >= 8) break;
    }
    if (commentSamples.length >= 8) break;
  }
  const url = String(first(post?.url, wrapper?.url, ''));
  posts.push({
    id,
    url,
    text: sourceText.slice(0, 1600),
    mention_matches: sourceText.match(mention)?.[0]?.trim() || cfg.brand,
    published_at: publishedAt,
    author: { username, name: authorName, location: locationText.slice(0, 300), verified: Boolean(author?.verified) },
    belarus_evidence: countryCode === 'BY' ? 'country_code=BY' : (locationText.match(rb)?.[0] || sourceText.match(rb)?.[0] || 'Беларусь указана во входных данных'),
    metrics: {
      views: num(engagement?.views, engagement?.view_count, post?.views_count, wrapper?.views),
      likes: num(engagement?.likes, engagement?.like_count, post?.likes_count, wrapper?.likes),
      replies: num(engagement?.replies, engagement?.comments, engagement?.reply_count, post?.reply_count, wrapper?.replies, wrapper?.comments_count),
      reposts: num(engagement?.reposts, engagement?.shares, engagement?.repost_count, post?.repost_count, wrapper?.reposts, wrapper?.shares),
    },
    comment_samples: commentSamples,
    comment_text_status: commentSamples.length ? 'available' : 'unavailable_from_socialcrawl',
  });
  if (posts.length >= 50) break;
}

if (!posts.length) return [];
return [{ json: { ...cfg, posts } }];

const agent = $input.first().json || {};
const batch = $('04 · Задание AI-аналитику').first().json;
const posts = batch.posts || [];
const raw = String(agent.output || agent.text || agent.response || '').trim();
let parsed = {};
try {
  const firstBrace = raw.indexOf('{');
  const lastBrace = raw.lastIndexOf('}');
  parsed = JSON.parse(firstBrace >= 0 && lastBrace > firstBrace ? raw.slice(firstBrace, lastBrace + 1) : raw);
} catch (_) { parsed = {}; }
const analyses = new Map((Array.isArray(parsed.analyses) ? parsed.analyses : []).map((value) => [String(value.id), value]));
const summary = parsed.batch_summary || {};
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const nl = (value) => esc(value).replace(/\n/g, '<br>');
const fmt = (value) => new Intl.NumberFormat('ru-RU').format(Math.round(Number(value) || 0));
const shorten = (value, limit) => String(value || '').length > limit ? String(value).slice(0, limit - 1) + '…' : String(value || '');
const localTime = (iso) => {
  try { return new Intl.DateTimeFormat('ru-RU', { timeZone: 'Europe/Minsk', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(iso)); }
  catch (_) { return String(iso || 'нет данных'); }
};
const sentimentMeta = {
  negative: { label: 'Негативно', icon: '🔴', color: '#d7263d', bg: '#fff1f3' },
  neutral: { label: 'Нейтрально', icon: '⚪', color: '#667085', bg: '#f2f4f7' },
  positive: { label: 'Позитивно', icon: '🟢', color: '#18864b', bg: '#edf7f0' },
};
const baseUrl = 'https://newsaccount.app.n8n.cloud';
const secret = 'local-brand-mentions-agent';
const cards = [];
const state = $getWorkflowStaticData('global');
state.brandMentionSent = state.brandMentionSent || {};
const nowMs = Date.now();

for (const post of posts) {
  const a = analyses.get(String(post.id));
  if (!a) continue;
  if (a.mandatory_filter_passed !== true) continue;
  if (String(a.content_language || '').toLowerCase() !== 'russian') continue;
  if (a.contains_profanity === true || a.geo_stop_detected === true || a.social_spam_detected === true) continue;
  if (a.is_belarus_sber !== true) continue;
  /* safety fallback disabled; AI must return a complete allowed analysis */
  const unusedFallback = {
    id: post.id, post_title: 'Упоминание ' + batch.brand, sentiment: 'neutral', sentiment_score: 0,
    summary: shorten(post.text, 240), mention_quote: post.mention_matches, should_respond: false,
    response_priority: 'low', reaction_recommendation: 'Проверить вручную: AI не вернул анализ.',
    response_idea: 'Уточнить контекст и при необходимости помочь.',
    comment_summary: post.comment_samples?.length ? post.comment_samples.join('; ') : 'Тексты комментариев недоступны; известно только количество ответов: ' + fmt(post.metrics?.replies),
    risk: 'Требуется ручная проверка', key_topics: [],
  };
  void unusedFallback;
  const sentiment = ['negative', 'neutral', 'positive'].includes(a.sentiment) ? a.sentiment : 'neutral';
  const sm = sentimentMeta[sentiment];
  const payloadData = {
    v: 1, id: post.id, u: post.url, b: batch.brand, t: shorten(post.text, 420), au: post.author?.username,
    h: shorten(a.post_title, 100), s: sentiment, sm: shorten(a.summary, 260), rr: shorten(a.reaction_recommendation, 260),
    ri: shorten(a.response_idea, 280), ts: nowMs,
  };
  const payload = Buffer.from(JSON.stringify(payloadData), 'utf8').toString('base64url');
  const actionUrl = baseUrl + '/webhook/brand-mention-ai-reply-v8?payload=' + encodeURIComponent(payload) + '&token=' + encodeURIComponent(secret);
  // Telegram callback_data ограничен 64 байтами. Контекст агент возьмёт
  // из самой информативной Telegram-карточки, поэтому здесь нужен короткий ID.
  const callbackKey = Buffer.from(String(post.id), 'utf8').toString('base64url').slice(0, 44);
  const telegramCallbackData = 'brand_reply:' + callbackKey;
  const metrics = post.metrics || {};
  const titleLink = post.url ? '<a href="' + esc(post.url) + '" style="color:#17212b;text-decoration:underline">' + esc(a.post_title) + '</a>' : esc(a.post_title);
  const commentLabel = post.comment_samples?.length ? esc(a.comment_summary) : 'Тексты комментариев SocialCrawl для Threads не вернул. Доступно только количество ответов: <b>' + fmt(metrics.replies) + '</b>.';
  const emailCard = [
    '<div style="margin:18px 0;background:#fff;border:1px solid #dde3ea;border-left:7px solid ' + sm.color + ';border-radius:12px;overflow:hidden">',
    '<div style="padding:20px 22px;background:' + sm.bg + '"><div style="font-size:13px;color:#667085">' + sm.icon + ' ' + sm.label + ' · ' + esc(String(a.response_priority || 'low').toUpperCase()) + '</div>',
    '<div style="font-size:21px;font-weight:700;margin-top:7px">' + titleLink + '</div></div>',
    '<div style="padding:20px 22px;line-height:1.55">',
    '<p><b>Автор:</b> @' + esc(post.author?.username) + ' · ' + esc(post.author?.name) + (post.author?.verified ? ' ✅' : '') + '<br>',
    '<b>Опубликовано / время упоминания:</b> ' + esc(localTime(post.published_at)) + ' (Минск)<br>',
    '<b>Подтверждение РБ:</b> ' + esc(post.belarus_evidence) + '<br>',
    '<b>Где упомянут бренд:</b> “' + esc(a.mention_quote || post.mention_matches) + '”</p>',
    '<p><b>📝 Сам пост пользователя:</b></p><div style="background:#f8fafc;padding:15px;border-radius:9px">' + nl(shorten(post.text, 1000)) + '</div>',
    '<table role="presentation" style="width:100%;border-collapse:collapse;text-align:center;margin:16px 0"><tr>',
    '<td style="border:1px solid #e1e5ea;padding:10px"><b>👁 ' + fmt(metrics.views) + '</b><br><span style="font-size:12px">охват</span></td>',
    '<td style="border:1px solid #e1e5ea;padding:10px"><b>❤️ ' + fmt(metrics.likes) + '</b><br><span style="font-size:12px">лайки</span></td>',
