const MINUTE = 60 * 1000;
const MINSK_OFFSET = 3 * 60 * MINUTE;
const now = new Date();
const localNow = new Date(now.getTime() + MINSK_OFFSET);
const year = localNow.getUTCFullYear();
const month = localNow.getUTCMonth();
const day = localNow.getUTCDate();
const hour = localNow.getUTCHours();

const toUtc = (yy, mm, dd, hh, mi, ss) =>
  new Date(Date.UTC(yy, mm, dd, hh, mi, ss) - MINSK_OFFSET);

const localDate = (date) => {
  const shifted = new Date(date.getTime() + MINSK_OFFSET);
  const pad = (value) => String(value).padStart(2, '0');
  return shifted.getUTCFullYear()
    + '-' + pad(shifted.getUTCMonth() + 1)
    + '-' + pad(shifted.getUTCDate());
};

