const cleanFilterText = (value) => String(value || '')
  .replace(/https?:\/\/\S+/giu, ' ')
  .replace(/www\.\S+/giu, ' ')
  .replace(/@[\p{L}\p{N}_.]+/gu, ' ')
  .replace(/#[\p{L}\p{N}_]+/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const isRussianText = (value) => {
  const filter = cfg.language_filter || {};
  if (!filter.enabled) return true;
  const source = cleanFilterText(value);
  const letters = source.match(/\p{L}/gu) || [];
  if (!letters.length) return false;
  const russianCount = (source.match(/[А-Яа-яЁё]/g) || []).length;
  const latinCount = (source.match(/[A-Za-z]/g) || []).length;
  const foreignCyrillicCount = (source.match(/[ІіЇїЄєҐґЎў]/g) || []).length;
  return russianCount >= Number(filter.minRussianLetters || 5)
    && russianCount / letters.length >= Number(filter.minRussianShare || 0.70)
    && latinCount / letters.length <= Number(filter.maxLatinShare || 0.30)
    && (!filter.rejectForeignCyrillic || foreignCyrillicCount === 0);
};

