const fundraisingSignal = /(?:пожертв|благотвор|сбор\s+(?:денег|средств|на)|донат|помогите|нужна\s+помощь|материальн(?:ая|ой)\s+помощ|скиньте|переведите|поддержать\s+(?:деньгами|рубл)|на\s+лечени|номер\s+карт|реквизит|карта\s+сбер|на\s+сбер|сбер\s*[:—-]?\s*\d{4,})/iu;

const listOf = (body) => Array.isArray(body?.data?.items) ? body.data.items
  : Array.isArray(body?.items) ? body.items
  : Array.isArray(body?.data?.posts) ? body.data.posts
  : Array.isArray(body?.posts) ? body.posts
  : Array.isArray(body?.results) ? body.results
