const unique = new Map();
for (let index = 0; index < responses.length; index++) {
  const body = responses[index].json || {};
  const request = requestItems[index]?.json || {};
  const rows = listOf(body);
  diagnostics.search_credits_used += Number(body.credits_used || 0);
  diagnostics.search_returned_items += rows.length;
  diagnostics.search_by_query.push({
    query: request.search_query || ('query_' + (index + 1)),
    type: request.search_query_type || 'direct',
    returned: rows.length,
    credits_used: Number(body.credits_used || 0),
    cached: body.cached === true,
    request_id: String(body.request_id || ''),
  });

  for (const wrapper of rows) {
    const post = wrapper?.post || wrapper;
    const id = String(first(
      post?.id,
      wrapper?.id,
      post?.url,
      wrapper?.url,
      ''
    )).trim();
    if (!id) continue;
    const existing = unique.get(id);
    const candidate = { wrapper, request };
    // Прямой поисковый результат приоритетнее широкого запроса «банк».
    if (!existing || request.search_query_type === 'direct') {
      unique.set(id, candidate);
