  const engagement = post?.engagement || wrapper?.engagement || {};
  const flags = post?.flags || wrapper?.flags || {};
  const text = String(first(content?.text, post?.text, wrapper?.text, '')).trim();
  const parentUrl = String(first(post?.url, wrapper?.url, '')).trim();
  const username = String(first(
    author?.username,
    author?.handle,
