    )))
  );
  const searchHitIsComment = explicitReplySignal
    || Boolean(urlOwner && normalizedUsername && urlOwner !== normalizedUsername);
  const shortcode = String(first(
    post?.shortcode,
    post?.code,
    post?.post_code,
    post?.ext?.shortcode,
    post?.ext?.code,
    wrapper?.shortcode,
    wrapper?.code,
    wrapper?.post_code,
    wrapper?.ext?.shortcode,
    wrapper?.ext?.code,
    ''
  ) || '').trim();
  const constructedOwnUrl = normalizedUsername && shortcode
    ? 'https://www.threads.com/@' + username + '/post/' + shortcode
    : '';
  const explicitOwnUrl = String(first(
    post?.comment_url,
    post?.reply_url,
    post?.permalink,
    post?.ext?.comment_url,
    post?.ext?.reply_url,
    post?.ext?.permalink,
    wrapper?.comment_url,
    wrapper?.reply_url,
    wrapper?.permalink,
    wrapper?.ext?.comment_url,
    wrapper?.ext?.reply_url,
    wrapper?.ext?.permalink,
    ''
  ) || '').trim();
  const explicitOwnUrlOwner = String(
    explicitOwnUrl.match(/threads\.(?:com|net)\/@([^/]+)\/post\//iu)?.[1] || ''
  ).replace(/^@/, '').toLowerCase();
  const candidateOwnUrl = explicitOwnUrl
    && explicitOwnUrlOwner === normalizedUsername
      ? explicitOwnUrl
      : constructedOwnUrl;
  const commentUrl = searchHitIsComment
    && candidateOwnUrl
      ? candidateOwnUrl
      : '';
  const url = parentUrl;
  if (!text || !url) {
    diagnostics.rejected_no_text_or_url++;
    continue;
  }

  const direct = mention.test(text);
  const bankPost = bankContext.test(text);
  const canInspectComments = cfg.enable_comment_search
    && entry.request?.search_query_type === 'comment_discovery'
    && bankPost;
  if (!direct && !canInspectComments) {
    diagnostics.rejected_no_direct_or_bank_context++;
    continue;
  }

  const publishedAt = String(first(
    post?.published_at,
    wrapper?.published_at,
    post?.created_at,
    wrapper?.created_at,
    ''
  ));
  const publishedMs = Date.parse(publishedAt);
  if (cfg.use_date_filter && (
    !Number.isFinite(publishedMs)
    || publishedMs < startMs
    || publishedMs > endMs
  )) {
    diagnostics.rejected_time++;
    continue;
  }
  if (cfg.strict_russian_only && !isRussianText(text)) {
    diagnostics.rejected_non_russian++;
    diagnostics.rejected_language_details.push({
      post_id: id,
      reason: 'текст не является русскоязычным',
    });
    continue;
  }
  const profanityMatch = cfg.reject_profanity
    ? text.match(profanityStop)?.[0] || ''
    : '';
  if (profanityMatch) {
    diagnostics.rejected_profanity++;
    diagnostics.rejected_profanity_details.push({
      post_id: id,
      matched: profanityMatch,
    });
    continue;
  }
  const socialSpamMatch = cfg.reject_social_spam
    ? text.match(socialSpamStop)?.[0] || ''
    : '';
  if (socialSpamMatch) {
    diagnostics.rejected_social_spam++;
    diagnostics.rejected_social_spam_details.push({
      post_id: id,
      matched: socialSpamMatch,
    });
    continue;
  }
  const blockedTopic = detectStopTopic(text);
  if (cfg.use_safety_filter && (flags?.nsfw === true || blockedTopic)) {
    diagnostics.rejected_safety++;
    diagnostics.rejected_stop_topic_details.push({
      post_id: id,
      blocked_topic: flags?.nsfw === true ? '18+ / NSFW' : blockedTopic,
    });
    continue;
  }

  const authorName = String(first(author?.display_name, author?.name, username));
  const locationText = [
    author?.location, author?.bio, author?.country,
    post?.location, post?.place, post?.geo,
    wrapper?.location, wrapper?.place, wrapper?.geo,
  ].map(textOf).join(' ');
  const countryCode = String(first(
    author?.country_code,
    post?.country_code,
    wrapper?.country_code,
    ''
  )).toUpperCase();
  const searchable = [text, username, authorName, locationText].join(' ');
  const authorIsOfficialByHandle = officialHandles.has(normalizedUsername);
  const mentionsOfficialByHandle = /@sberbankby\b/iu.test(searchable);
  const explicitByBrand = rbBrand.test(searchable);
  const rbMatch = searchable.match(rb)?.[0] || '';
  const geoStopMatch = cfg.geo_stop_enabled
    ? searchable.match(geoStop)?.[0] || ''
    : '';
