  // Само упоминание не определяет рынок и передаётся ИИ для смысловой оценки.
  if (geoStopMatch) {
    diagnostics.passed_geo_mentions_to_ai++;
    diagnostics.passed_geo_mentions_to_ai_details.push({
      post_id: id,
      matched: geoStopMatch,
      decision: 'передано ИИ; контекстное упоминание страны не блокирует пост',
    });
  }
  const hasRbEvidence = countryCode === 'BY'
    || authorIsOfficialByHandle
    || mentionsOfficialByHandle
    || explicitByBrand
    || Boolean(rbMatch);
  // Из текста не выводим иностранный рынок по одному слову или городу.
  // Код страны из метаданных остаётся полезной подсказкой для ИИ.
  const hasRuEvidence = countryCode === 'RU';

  const region = hasRbEvidence ? 'BY' : (hasRuEvidence ? 'RU' : 'UNKNOWN');
  let regionEvidence = 'регион не определён; иностранный рынок не выводится по одному упоминанию';
  if (countryCode === 'BY') regionEvidence = 'country_code=BY';
  else if (authorIsOfficialByHandle) regionEvidence = 'автор — официальный аккаунт банка';
  else if (mentionsOfficialByHandle) regionEvidence = 'упоминание @sberbankby';
  else if (explicitByBrand) {
    regionEvidence = searchable.match(rbBrand)?.[0] || 'белорусское обозначение банка';
  } else if (rbMatch) regionEvidence = rbMatch;
  else if (countryCode === 'RU') regionEvidence = 'country_code=RU';

  // В Threads это две разные метрики. Во всём дальнейшем flow
  // metrics.reposts всегда означает их сумму: репосты + «поделиться».
  const repostsOnly = num(
    engagement?.reposts,
    engagement?.repost_count,
    engagement?.reposts_count,
    post?.reposts,
    post?.repost_count,
    post?.reposts_count
  );
  // SocialCrawl может вернуть счётчик с иконки «Поделиться» как
  // shares, saves или reshares. Это альтернативные представления одной
  // метрики, поэтому берём максимум, а не складываем их между собой.
  const shares = Math.max(
    num(
      engagement?.shares,
      engagement?.share_count,
      engagement?.shares_count,
      post?.shares,
      post?.share_count,
      post?.shares_count,
      post?.ext?.shares,
      post?.ext?.share_count,
      post?.ext?.shares_count
    ),
    num(
      engagement?.saves,
      engagement?.save_count,
      engagement?.saves_count,
      engagement?.reshares,
      engagement?.reshare_count,
      engagement?.reshares_count,
      post?.saves,
      post?.save_count,
      post?.saves_count,
      post?.reshares,
      post?.reshare_count,
      post?.reshares_count,
      post?.ext?.saves,
      post?.ext?.save_count,
      post?.ext?.reshares,
      post?.ext?.reshare_count
    )
  );

  const candidate = {
    id,
    url,
    text: text.slice(0, 1600),
    published_at: publishedAt,
    author: {
      username,
      name: authorName,
      location: locationText.slice(0, 300),
      verified: Boolean(author?.verified),
    },
    region,
    region_evidence: regionEvidence,
    belarus_evidence: regionEvidence,
    direct_brand_mention: direct,
    direct_comment_mention: direct && searchHitIsComment,
    search_hit_is_comment: searchHitIsComment,
    parent_post_url: searchHitIsComment ? parentUrl : '',
    detected_comment_url: searchHitIsComment ? commentUrl : '',
    needs_comments: !direct && canInspectComments,
    mention_matches: direct
      ? (text.match(mention)?.[0]?.trim() || cfg.brand)
      : '',
    fundraising_only_signal: fundraisingSignal.test(text),
    metrics: {
      views: nullableNum(
        engagement?.views,
        engagement?.view_count,
        engagement?.views_count,
        post?.views,
        post?.view_count,
        post?.views_count,
        post?.ext?.views,
        post?.ext?.view_count
      ),
      likes: num(engagement?.likes, engagement?.like_count, post?.likes_count),
      replies: num(
        engagement?.replies,
        engagement?.comments,
        engagement?.reply_count,
        post?.reply_count,
        post?.comments_count
      ),
      reposts_only: repostsOnly,
      shares,
      reposts: repostsOnly + shares,
    },
    raw_search_post: wrapper,
  };

  if (direct) {
    diagnostics.accepted_direct++;
    directCandidates.push(candidate);
  } else {
    diagnostics.accepted_comment_candidates++;
    commentCandidates.push(candidate);
  }
}

const commentLimit = Math.max(0, Number(
  cfg.max_comment_candidates_per_run || 0
