  },
  { topic: 'межнациональные конфликты', pattern: /(?:межнациональн\p{L}*|межэтническ\p{L}*|этническ\p{L}*\s+конфликт\p{L}*)/iu },
  { topic: 'конфликты', pattern: /(?:конфликт\p{L}*|противостояни\p{L}*)/iu },
  { topic: 'аборты', pattern: /(?:аборт\p{L}*|прерыван\p{L}*\s+беременн\p{L}*)/iu },
