  { topic: 'цензура', pattern: /(?:цензур\p{L}*|censorship\p{L}*)/iu },
  { topic: 'отношения мужчины и женщины', pattern: /(?:(?:отношени\p{L}*|взаимоотношени\p{L}*)[\s\S]{0,80}(?:мужчин\p{L}*|парн\p{L}*)[\s\S]{0,80}(?:женщин\p{L}*|девуш\p{L}*)|(?:отношени\p{L}*|взаимоотношени\p{L}*)[\s\S]{0,80}(?:женщин\p{L}*|девуш\p{L}*)[\s\S]{0,80}(?:мужчин\p{L}*|парн\p{L}*))/iu },
  { topic: 'домашнее насилие', pattern: /(?:домашн\p{L}*\s+насили\p{L}*|семейн\p{L}*\s+насили\p{L}*|абьюз\p{L}*)/iu },
  { topic: 'излишне откровенные обсуждения физиологии и интимных подробностей', pattern: /(?:интимн\p{L}*\s+подробност\p{L}*|половы\p{L}*\s+орган\p{L}*|менструац\p{L}*|эякуляц\p{L}*|дефекац\p{L}*|откровенн\p{L}*[\s\S]{0,50}физиологи\p{L}*)/iu },
  { topic: 'пропаганда чайлдфри', pattern: /(?:чайлдфри\p{L}*|childfree\p{L}*|пропаганд\p{L}*[\s\S]{0,60}(?:бездетн\p{L}*|отказ\p{L}*\s+от\s+дет\p{L}*))/iu },
  { topic: 'вопросы гендерного равенства', pattern: /(?:гендерн\p{L}*\s+равенств\p{L}*|гендерн\p{L}*\s+неравенств\p{L}*|gender\s+equality)/iu },
  { topic: 'эйджизм', pattern: /(?:эйджизм\p{L}*|ageism\p{L}*|дискриминаци\p{L}*\s+по\s+возраст\p{L}*)/iu },
  { topic: 'дискриминация', pattern: /(?:дискриминаци\p{L}*|discrimination\p{L}*)/iu },
  { topic: 'расизм', pattern: /(?:расизм\p{L}*|расист\p{L}*|racism\p{L}*)/iu },
  { topic: 'атрибуты запрещённых субкультур', pattern: /(?:запрещ[её]нн\p{L}*\s+субкультур\p{L}*|экстремистск\p{L}*\s+символик\p{L}*|свастик\p{L}*)/iu },
  { topic: 'национализм', pattern: /(?:национализм\p{L}*|националист\p{L}*|nationalism\p{L}*)/iu },
  { topic: 'нацизм', pattern: /(?:нацизм\p{L}*|нацист\p{L}*|неонаци\p{L}*|nazism\p{L}*)/iu },
  { topic: 'наркотические вещества', pattern: /(?:наркот\p{L}*|кокаин\p{L}*|героин\p{L}*|метамфетамин\p{L}*|марихуан\p{L}*|каннабис\p{L}*)/iu },
  { topic: 'оружие', pattern: /(?:оружи\p{L}*|пистолет\p{L}*|винтовк\p{L}*|боеприпас\p{L}*|огнестрельн\p{L}*)/iu },
  { topic: 'суицид', pattern: /(?:суицид\p{L}*|самоубийств\p{L}*|поконч\p{L}*\s+с\s+собой)/iu },
  { topic: '18+ и порнографический или эротический контент', pattern: /(?:18\s*\+|порн\p{L}*|эрот\p{L}*|onlyfans)/iu },
  { topic: 'проституция и эскорт', pattern: /(?:эскорт\p{L}*|проститу\p{L}*)/iu },
  { topic: 'азартные игры и букмекерство', pattern: /(?:казино\p{L}*|букмекер\p{L}*)/iu },
  { topic: 'военные действия, санкции, митинги и протесты', pattern: /(?:санкци\p{L}*|военн\p{L}*\s+(?:действ\p{L}*|операци\p{L}*|конфликт\p{L}*)|обстрел\p{L}*|ракет\p{L}*[\s-]*(?:удар\p{L}*|обстрел\p{L}*|атак\p{L}*)|фронт\p{L}*|оккупаци\p{L}*|бомбардировк\p{L}*|боев\p{L}*[\s-]*(?:действ\p{L}*|столкновени\p{L}*)|оппозици\p{L}*|митинг\p{L}*|протест\p{L}*)/iu },
];
const detectStopTopic = (value) => {
  const source = String(value || '').replace(/\s+/g, ' ').trim();
  for (const rule of STOP_TOPIC_RULES) {
    if (rule.pattern.test(source)) return rule.topic;
  }
  return '';
};

const cleanCommentFilterText = (value) => String(value || '')
  .replace(/https?:\/\/\S+/giu, ' ')
  .replace(/www\.\S+/giu, ' ')
  .replace(/@[\p{L}\p{N}_.]+/gu, ' ')
  .replace(/#[\p{L}\p{N}_]+/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const isRussianText = (value) => {
  const filter = batch.language_filter || {};
  if (!filter.enabled) return true;
  const source = cleanCommentFilterText(value);
  const letters = source.match(/\p{L}/gu) || [];
  if (!letters.length) return false;
  const russianCount = (source.match(/[А-Яа-яЁё]/g) || []).length;
  const latinCount = (source.match(/[A-Za-z]/g) || []).length;
  const foreignCyrillicCount = (source.match(/[ІіЇїЄєҐґЎў]/g) || []).length;
  return russianCount >= Number(filter.minRussianLetters || 5)
    && russianCount / letters.length >= Number(filter.minRussianShare || 0.70)
    && latinCount / letters.length <= Number(filter.maxLatinShare || 0.30)
    && (!filter.rejectForeignCyrillic || foreignCyrillicCount === 0);
};

const profanityStop = new RegExp(batch.profanity_pattern || '(?!)', 'iu');
const socialSpamStop = new RegExp(batch.social_spam_pattern || '(?!)', 'iu');

const rb = /(?:беларус|белорус|беларуск|belarus|\bby\b|\bbyn\b|минск|minsk|гомел|gomel|homiel|брест|brest|витебск|vitebsk|могил[её]в|mogilev|гродно|grodno|hrodna|бобруйск|баранович|полоцк|новополоцк|солигорск|жодино|лида|пинск|мозыр|орша|борисов|молодечно|\bрб\b|бел\.?\s*руб|\+375)/iu;
const rbBrand = /(?:@?sberbankby\b|sber-bank\.by|бпс[\s-]*сбербанк|оао\s*[«"']?сбер\s*банк)/iu;

const normalizeUrl = (value) => String(value || '')
  .replace(/threads\.net/iu, 'threads.com')
  .replace(/\/+$/, '')
  .trim();

const collectComments = (roots) => {
  const found = [];
  const byKey = new Map();
  const visit = (value, depth = 0, inheritedUrl = '') => {
    if (value == null || depth > 6 || found.length >= 200) return;
    if (Array.isArray(value)) {
      for (const entry of value) visit(entry, depth + 1, inheritedUrl);
      return;
    }
    if (typeof value !== 'object') return;

    const author = value?.author || value?.user || value?.owner
      || value?.post?.author || value?.reply?.author || {};
    const username = String(first(
      author?.username,
      author?.handle,
      value?.author_username,
      value?.username,
      value?.post?.author_username,
      value?.reply?.author_username,
      ''
    )).replace(/^@/, '').trim();
    const shortcode = String(first(
      value?.shortcode,
      value?.code,
      value?.post_code,
      value?.post?.shortcode,
      value?.post?.code,
      value?.reply?.shortcode,
      value?.reply?.code,
      value?.ext?.shortcode,
      value?.post?.ext?.shortcode,
      value?.reply?.ext?.shortcode,
      ''
    )).trim();
    const constructedUrl = username && shortcode
      ? 'https://www.threads.com/@' + username + '/post/' + shortcode
      : '';
    const explicitUrl = String(first(
      value?.permalink,
      value?.url,
      value?.comment_url,
      value?.reply_url,
      value?.share_url,
      value?.web_url,
      value?.ext?.permalink,
      value?.ext?.url,
      value?.content?.permalink,
      value?.content?.url,
      value?.post?.permalink,
      value?.post?.url,
      value?.post?.ext?.permalink,
      value?.post?.ext?.url,
      value?.reply?.permalink,
      value?.reply?.url,
      value?.reply?.ext?.permalink,
      value?.reply?.ext?.url,
      ''
    )).trim();
    const url = explicitUrl || constructedUrl || inheritedUrl;
    const id = String(first(
      value?.comment_id,
      value?.reply_id,
      value?.id,
      value?.pk,
      value?.post?.id,
      value?.reply?.id,
      ''
    )).trim();
    const text = String(first(
      value?.content?.text,
      value?.text,
      value?.body,
      value?.comment_text,
      value?.post?.content?.text,
      value?.post?.text,
      value?.reply?.content?.text,
      value?.reply?.text,
      ''
    )).trim();

    if (text) {
      const key = id || (username && shortcode
        ? username + '|' + shortcode
        : text);
      const existing = byKey.get(key);
      if (existing) {
        if (!existing.url && url) existing.url = url;
        if (!existing.id && id) existing.id = id;
      } else {
        const record = {
          id,
          url,
          text: text.slice(0, 1000),
          username,
          author_name: String(first(author?.display_name, author?.name, username, '')),
