};

const posts = [];
let commentCreditsUsed = 0;
let commentRequests = 0;
let rejectedWithoutBrandComment = 0;
let rejectedOfficialComments = 0;
let rejectedCommentSafety = 0;
let rejectedCommentLanguage = 0;
let rejectedCommentProfanity = 0;
let rejectedCommentSocialSpam = 0;
let rejectedCommentGeo = 0;
const rejectedCommentStopTopics = [];
let rejectedCommentRussia = 0;

const officialHandles = new Set(
  (batch.official_brand_handles || [])
    .map((value) => String(value).replace(/^@/, '').trim().toLowerCase())
    .filter(Boolean)
);
const isOfficialAuthor = (username) => batch.ignore_official_authors === true
  && officialHandles.has(String(username || '').replace(/^@/, '').trim().toLowerCase());

for (const item of items) {
  const directSearchComment = item.direct_comment_mention === true
    || item.search_hit_is_comment === true;
  const direct = item.direct_brand_mention === true && !directSearchComment;
  const response = item.comments_response || {};
  if (item.needs_comments) {
    commentRequests++;
    commentCreditsUsed += Number(response.credits_used || 0);
  }
  const commentRoots = [
    response?.data?.items,
    response?.items,
    response?.data?.comments,
    response?.comments,
  ].filter((value) => value !== undefined && value !== null);
  const collectedComments = collectComments(commentRoots);
  if (directSearchComment) {
    collectedComments.unshift({
      id: String(item.id || ''),
      url: String(item.detected_comment_url || ''),
      text: String(item.text || ''),
      username: String(item.author?.username || ''),
      author_name: String(item.author?.name || ''),
    });
  }
  const comments = collectedComments.filter((record) => {
    if (isOfficialAuthor(record.username)) {
      rejectedOfficialComments++;
      return false;
    }
    return true;
  });
  const brandComments = comments.filter((record) => mention.test(record.text));

  if (!direct && !brandComments.length) {
    rejectedWithoutBrandComment++;
    continue;
  }
  const brandCommentText = brandComments.map((record) => record.text).join(' ');
  if (!direct) {
    if (batch.strict_russian_only && !isRussianText(brandCommentText)) {
      rejectedCommentLanguage++;
      continue;
    }
    if (batch.reject_profanity && profanityStop.test(brandCommentText)) {
      rejectedCommentProfanity++;
      continue;
    }
    if (batch.reject_social_spam && socialSpamStop.test(brandCommentText)) {
      rejectedCommentSocialSpam++;
      continue;
    }
    // Географические упоминания в комментариях передаются ИИ:
    // комментарий о другой стране не является самостоятельной причиной отказа.
    const blockedCommentTopic = detectStopTopic(brandCommentText);
    if (batch.use_safety_filter && blockedCommentTopic) {
      rejectedCommentSafety++;
      rejectedCommentStopTopics.push({
        post_id: String(item.id || ''),
        blocked_topic: blockedCommentTopic,
      });
      continue;
    }
  }

  let region = item.region || 'UNKNOWN';
  let regionEvidence = item.region_evidence || 'нет данных';
  if (!direct && brandCommentText) {
    const commentHasBy = rbBrand.test(brandCommentText) || rb.test(brandCommentText);
    if (commentHasBy) {
      region = 'BY';
